insert into public.cases (id,number,title,category,difficulty,duration_min,summary,scenario,objectives,patient,vitals,history,"references",scoring,published) values ('pre-anesthesia-assessment',1,'Asesmen Pra-Anestesi','pre-anesthesia','BEGINNER',10,'Lakukan asesmen pasien elektif di ruang persiapan pra-operasi dan sampaikan temuan penting kepada tim anestesi.','Kamu adalah perawat anestesi di ruang persiapan pra-operasi. Seorang pasien dijadwalkan operasi elektif pagi ini. Lengkapi asesmen pra-anestesi secara terstruktur dan pastikan tim anestesi mengetahui semua informasi penting sebelum induksi.','["Mengidentifikasi pasien dan prosedur dengan benar","Mengikuti alur asesmen pra-anestesi yang logis","Menemukan celah keselamatan pada daftar periksa pra-operasi","Mengomunikasikan dan mendokumentasikan informasi alergi baru"]'::jsonb,'{"sex":"Perempuan","age":38,"procedure":"Kolesistektomi laparoskopik elektif","note":"IMT 24, tidak merokok"}'::jsonb,'{"bp":"128/78","hr":82,"spo2":98,"temp":36.7,"rr":16}'::jsonb,'["Tidak ada penyakit kronis; tidak minum obat rutin","Pernah apendektomi dengan anestesi umum 10 tahun lalu, tidak ada komplikasi yang dilaporkan","Tidak merokok, tidak minum alkohol","Catatan di status saat pendaftaran: ''Tidak ada alergi yang diketahui''"]'::jsonb,'[{"title":"Practice Advisory for Preanesthesia Evaluation","org":"American Society of Anesthesiologists (ASA)"},{"title":"ASA Physical Status Classification System","org":"ASA"},{"title":"Practice Guidelines for Preoperative Fasting","org":"ASA"}]'::jsonb,null,true)
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('pre-anesthesia-assessment','s1',0,'mcq','Kontak pertama',null,'Pasien baru tiba di ruang persiapan. Apa yang kamu lakukan PERTAMA?','Identifikasi Pasien',true,false,null,null,'Identifikasi yang benar dan konfirmasi prosedur mencegah kesalahan pasien dan kesalahan prosedur. Langkah ini dilakukan sebelum asesmen, diskusi persetujuan, atau pemberian obat apa pun.','Kenali pasien dan prosedurnya lebih dulu. Semua langkah lain bergantung pada ini.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Memverifikasi identitas dengan dua identitas pasien dan mengonfirmasi prosedur yang direncanakan bersama pasien dan status"},{"id":"b","text":"Langsung memeriksa jalan napas pasien"},{"id":"c","text":"Meminta pasien segera menandatangani formulir persetujuan"},{"id":"d","text":"Memberikan premedikasi untuk mengurangi kecemasan"}],"correct":"a"}'::jsonb from public.case_steps where case_id='pre-anesthesia-assessment' and step_key='s1'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('pre-anesthesia-assessment','s2',1,'sequence','Alur asesmen',null,'Susun alur asesmen pra-anestesi dalam urutan yang logis.','Asesmen Pasien',false,false,null,null,'Riwayat memandu apa yang dicari saat pemeriksaan, dan keduanya menentukan pemeriksaan penunjang yang relevan. Persetujuan dipastikan setelah rencana jelas, dan temuan dicatat serta dikomunikasikan paling akhir. Urutan bisa sedikit berbeda antar institusi; station ini mengikuti alur riwayat, pemeriksaan, penunjang, persetujuan, komunikasi.','Riwayat dulu, lalu pemeriksaan, penunjang, persetujuan, dan komunikasi.')
insert into public.questions (step_id,payload) select id, '{"items":[{"id":"i1","text":"Menelaah riwayat penyakit, pembedahan, dan anestesi sebelumnya"},{"id":"i2","text":"Memastikan alergi, obat yang sedang dikonsumsi, dan pertanyaan keselamatan lainnya"},{"id":"i3","text":"Melakukan pemeriksaan fisik terfokus, termasuk jalan napas"},{"id":"i4","text":"Menelaah pemeriksaan penunjang yang relevan"},{"id":"i5","text":"Memastikan persetujuan tindakan sudah terdokumentasi dan dipahami pasien"},{"id":"i6","text":"Mencatat hasil asesmen dan menyampaikan temuan kepada tim anestesi"}]}'::jsonb from public.case_steps where case_id='pre-anesthesia-assessment' and step_key='s2'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('pre-anesthesia-assessment','s3',2,'find-error','Telaah daftar periksa',null,'Telaah daftar periksa pra-operasi di bawah. Entri mana yang harus dikoreksi sebelum pasien dibawa ke kamar operasi?','Keselamatan',true,false,null,null,'Dua entri tidak aman: waktu puasa yang tidak memenuhi panduan umum ditandai cukup, dan bagian alergi dikosongkan. Keduanya dapat membahayakan pasien bila tidak dikoreksi sebelum induksi.','Jangan terima entri daftar periksa sebagai beres sebelum diverifikasi dan sesuai fakta.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Pilih semua entri yang salah atau tidak aman.","items":[{"id":"c1","label":"Gelang identitas sesuai status: nama dan tanggal lahir diperiksa","correct":false,"why":"Pemeriksaan identitas sudah tepat."},{"id":"c2","label":"Prosedur pada formulir persetujuan sesuai dengan jadwal operasi","correct":false,"why":"Persetujuan dan jadwal sudah sesuai."},{"id":"c3","label":"Puasa: makan padat terakhir 4 jam lalu, ditandai ''cukup, lanjutkan''","correct":true,"why":"Panduan puasa ASA yang umum adalah minimal 6 jam setelah makanan ringan dan lebih lama setelah makanan berlemak. 4 jam tidak cukup; dokter anestesi harus diberi tahu."},{"id":"c4","label":"Obat yang sedang dikonsumsi: tidak ada, sudah dicatat","correct":false,"why":"Sudah dicatat dengan benar."},{"id":"c5","label":"Bagian alergi: dikosongkan (''nanti ditanyakan'')","correct":true,"why":"Status alergi harus ditanyakan secara aktif dan dicatat sebelum anestesi, tidak boleh dikosongkan."},{"id":"c6","label":"Tanda vital dasar sudah diukur dan dicatat","correct":false,"why":"Nilai dasar sudah terdokumentasi."}]}'::jsonb from public.case_steps where case_id='pre-anesthesia-assessment' and step_key='s3'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('pre-anesthesia-assessment','s4',3,'branching','Informasi alergi baru','Saat menelaah riwayat, pasien mengatakan ia pernah gatal-gatal dan ruam kulit setelah minum amoksisilin waktu kecil. Di status tertulis ''Tidak ada alergi yang diketahui''.','Tindakan apa yang paling tepat?','Komunikasi',true,false,null,'["Pasien melaporkan ruam dan gatal setelah minum amoksisilin (masa kecil)"]'::jsonb,'Setiap reaksi obat yang dilaporkan harus digali, dicatat, dan dikomunikasikan. Reaksi yang tampak ringan pun memengaruhi pilihan obat oleh tim.','Alergi yang dilaporkan berarti gali, catat, dan komunikasikan. Ketiganya.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Menggali detailnya (obat, reaksi, waktu), mencatatnya sebagai alergi yang dilaporkan, dan memberi tahu tim anestesi sebelum tindakan","score":100,"consequence":"Alergi tercatat dan ditandai. Tim anestesi dapat mempertimbangkannya saat merencanakan obat untuk kasus ini."},{"id":"b","text":"Menuliskannya di catatan tetapi tidak memberi tahu siapa pun karena status sudah ditandatangani","score":40,"consequence":"Sudah tercatat, tetapi tim mungkin tidak melihatnya tepat waktu. Dokumentasi tanpa komunikasi masih menyisakan celah."},{"id":"c","text":"Mengabaikannya: ruam waktu kecil kecil kemungkinan berpengaruh","score":0,"consequence":"Reaksi tersebut tidak tercatat dan tim tidak mengetahuinya.","remedial":"r1"},{"id":"d","text":"Menunggu apakah dokter bedah menanyakan alergi","score":0,"consequence":"Bisa jadi tidak ada yang bertanya, dan informasinya hanya ada padamu.","remedial":"r1"}]}'::jsonb from public.case_steps where case_id='pre-anesthesia-assessment' and step_key='s4'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('pre-anesthesia-assessment','r1',4,'mcq','Lanjutan: antibiotik profilaksis','Tim kini menyiapkan antibiotik profilaksis rutin. Di status masih tertulis ''Tidak ada alergi yang diketahui''.','Kamu ingat apa yang dikatakan pasien. Apa yang kamu lakukan sekarang?','Komunikasi',false,true,null,null,'Setiap anggota tim bertanggung jawab bersuara saat informasi keselamatan pasien bertentangan dengan status. Waktu yang tepat adalah sebelum obat diberikan.','Jika kamu tahu sesuatu yang memengaruhi keselamatan, bicara sebelum tindakan, bukan sesudahnya.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Segera bicara: memberi tahu dokter anestesi tentang reaksi yang dilaporkan agar diverifikasi sebelum antibiotik apa pun diberikan"},{"id":"b","text":"Diam saja karena itu bukan tanggung jawabmu"},{"id":"c","text":"Menunggu sampai dokter bedah selesai"},{"id":"d","text":"Memberikan antibiotik perlahan sambil mengamati pasien"}],"correct":"a"}'::jsonb from public.case_steps where case_id='pre-anesthesia-assessment' and step_key='r1'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('pre-anesthesia-assessment','s5',5,'mcq','Pemeriksaan penunjang',null,'Pasien ini umumnya sehat tanpa penyakit kronis. Pernyataan mana tentang pemeriksaan penunjang pra-operasi yang paling tepat?','Berpikir Kritis',false,false,null,null,'Panduan praktik terkini mendukung pemeriksaan yang selektif dan berdasarkan indikasi, sesuai riwayat, pemeriksaan fisik, dan jenis operasi. Pemeriksaan rutin pada pasien sehat menambah biaya dan hasil positif palsu tanpa manfaat yang jelas.','Minta dan telaah pemeriksaan karena ada alasannya, bukan karena kebiasaan.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Pemeriksaan dipilih berdasarkan kondisi klinis pasien dan operasi yang direncanakan, bukan diminta rutin untuk semua orang"},{"id":"b","text":"Setiap pasien membutuhkan panel lengkap pemeriksaan darah, foto toraks, dan EKG"},{"id":"c","text":"Pemeriksaan penunjang tidak pernah diperlukan sebelum operasi"},{"id":"d","text":"Hanya dokter bedah yang menentukan pemeriksaan yang relevan"}],"correct":"a"}'::jsonb from public.case_steps where case_id='pre-anesthesia-assessment' and step_key='s5'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('pre-anesthesia-assessment','s6',6,'mcq','Kelas ASA','Ringkasan: usia 38 tahun, IMT 24, tidak merokok, tidak ada penyakit sistemik, tidak minum obat rutin, direncanakan kolesistektomi laparoskopik elektif.','Klasifikasi ASA Physical Status mana yang paling sesuai untuk pasien ini?','Asesmen Pasien',false,false,null,null,'Pasien sehat, tidak merokok, tanpa penyakit sistemik adalah ASA I. Klasifikasi akhir ditetapkan oleh dokter anestesi; perananmu adalah memberikan informasi yang akurat untuk keputusan itu.','Kelas ASA mencerminkan kesehatan sistemik, bukan jenis operasi yang direncanakan.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"ASA I: pasien sehat normal"},{"id":"b","text":"ASA II: pasien dengan penyakit sistemik ringan"},{"id":"c","text":"ASA III: pasien dengan penyakit sistemik berat"},{"id":"d","text":"ASA IV: penyakit sistemik berat yang merupakan ancaman konstan bagi hidup"}],"correct":"a"}'::jsonb from public.case_steps where case_id='pre-anesthesia-assessment' and step_key='s6'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('pre-anesthesia-assessment','s7',7,'mcq','Dokumentasi',null,'Catatan mana yang paling mencerminkan dokumentasi asesmen pra-anestesi yang baik?','Dokumentasi',false,false,null,null,'Catatan adalah sumber kebenaran bersama seluruh tim. Harus akurat, lengkap, terbaca, bertanda waktu, dan ditandatangani untuk pasien ini. Menyalin catatan pasien lain berisiko menimbulkan kesalahan serius.','Jika tidak terdokumentasi, orang berikutnya tidak bisa mengandalkannya.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Catatan yang terbaca jelas, bertanda waktu dan tanda tangan, berisi riwayat, alergi, status puasa, temuan jalan napas, kelas ASA, dan apa yang sudah dikomunikasikan ke tim"},{"id":"b","text":"Laporan lisan sudah cukup; menulis bisa menunggu sampai setelah operasi"},{"id":"c","text":"Hanya tanda vital, karena sisanya sudah ada di catatan dokter bedah"},{"id":"d","text":"Menyalin catatan pasien lain lalu mengganti namanya"}],"correct":"a"}'::jsonb from public.case_steps where case_id='pre-anesthesia-assessment' and step_key='s7'
insert into public.cases (id,number,title,category,difficulty,duration_min,summary,scenario,objectives,patient,vitals,history,"references",scoring,published) values ('airway-management',2,'Asesmen dan Persiapan Jalan Napas','airway','INTERMEDIATE',12,'Kenali tanda jalan napas sulit, siapkan peralatan, dan bantu urutan intubasi yang aman.','Kamu membantu dokter anestesi sebelum anestesi umum. Tugasmu mengenali risiko jalan napas, menyiapkan peralatan, mendukung urutan intubasi, dan merespons dengan benar saat konfirmasi posisi pipa gagal.','["Mengenali temuan yang memprediksi jalan napas sulit","Menyiapkan peralatan jalan napas utama dan cadangan","Mengikuti urutan persiapan jalan napas yang aman","Merespons kapnografi yang tidak menunjukkan gelombang setelah intubasi"]'::jsonb,'{"sex":"Laki-laki","age":52,"procedure":"Perbaikan hernia elektif dengan anestesi umum","note":"IMT 34"}'::jsonb,'{"bp":"134/84","hr":78,"spo2":97,"temp":36.8,"rr":16}'::jsonb,'["IMT 34, mendengkur saat tidur","Berjenggot lebat","Tidak ada alergi yang diketahui","Tidak ada masalah anestesi sebelumnya yang dilaporkan"]'::jsonb,'[{"title":"Practice Guidelines for Management of the Difficult Airway","org":"American Society of Anesthesiologists (ASA)"},{"title":"Standards for Basic Anesthetic Monitoring","org":"ASA"}]'::jsonb,null,true)
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('airway-management','s1',0,'equipment','Pemeriksaan jalan napas',null,'Temuan pemeriksaan tercantum di bawah. Mana yang menimbulkan kekhawatiran?','Penilaian Jalan Napas',true,false,null,null,'Mallampati III, jarak tiromental pendek, ekstensi leher terbatas, dan jenggot lebat adalah indikator risiko laringoskopi atau ventilasi masker yang sulit. Bukaan mulut memadai dan gigi utuh bukan masalah.','Cari kombinasi indikator risiko, bukan satu tanda saja.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Pilih SEMUA temuan yang menunjukkan kemungkinan jalan napas sulit.","items":[{"id":"f1","label":"Mallampati kelas III","correct":true,"why":"Struktur orofaring yang kurang terlihat dapat memprediksi laringoskopi sulit."},{"id":"f2","label":"Jarak tiromental sekitar 5 cm","correct":true,"why":"Jarak tiromental pendek dapat menandakan laring lebih anterior dan pandangan sulit."},{"id":"f3","label":"Ekstensi leher terbatas","correct":true,"why":"Ekstensi terbatas menyulitkan penyejajaran sumbu jalan napas."},{"id":"f4","label":"Jenggot lebat","correct":true,"why":"Jenggot dapat mengganggu perlekatan masker saat ventilasi bag-mask."},{"id":"f5","label":"Bukaan mulut sekitar 4 cm","correct":false,"why":"Bukaan mulut memadai; bukan faktor risiko."},{"id":"f6","label":"Gigi asli utuh, tidak ada yang goyang","correct":false,"why":"Gigi normal bukan indikator risiko."}]}'::jsonb from public.case_steps where case_id='airway-management' and step_key='s1'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('airway-management','s2',1,'mcq','Perencanaan','Kamu telah mengenali beberapa indikator risiko jalan napas sulit.','Respons apa yang paling tepat?','Manajemen Jalan Napas',true,false,null,null,'Panduan jalan napas sulit menekankan pengenalan masalah sejak dini serta strategi dan alat cadangan yang disiapkan sebelum induksi. Rencana dibuat oleh dokter anestesi bersama tim.','Antisipasi, komunikasikan, dan siapkan sebelum induksi.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Menyampaikan temuan kepada dokter anestesi dan memastikan peralatan jalan napas cadangan siap sebelum induksi"},{"id":"b","text":"Melanjutkan seperti biasa dan baru menangani masalah jika muncul"},{"id":"c","text":"Membatalkan operasi sendiri"},{"id":"d","text":"Menentukan rencana jalan napas setelah pasien tertidur"}],"correct":"a"}'::jsonb from public.case_steps where case_id='airway-management' and step_key='s2'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('airway-management','s3',2,'equipment','Siapkan meja jalan napas',null,'Item mana yang termasuk dalam persiapan jalan napas untuk pasien ini?','Persiapan Peralatan',true,false,null,null,'Persiapan mencakup suction, alat ventilasi, alat intubasi utama dalam beberapa ukuran, cadangan seperti sungkup laring dan video laringoskop, serta kapnografi. Item untuk prosedur lain tidak diperlukan.','Siapkan alat utama DAN cadangan, lalu uji sebelum induksi.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Pilih peralatan yang harus disiapkan untuk induksi ini.","items":[{"id":"e1","label":"Unit suction dengan kateter kaku, sudah diuji","correct":true,"why":"Suction harus berfungsi sebelum induksi."},{"id":"e2","label":"Bag-mask dengan sumber oksigen dan berbagai ukuran masker wajah yang pas","correct":true,"why":"Diperlukan untuk preoksigenasi dan ventilasi penyelamatan."},{"id":"e3","label":"Gagang laringoskop dan bilah, lampu sudah dicek","correct":true,"why":"Lampu yang mati adalah masalah yang bisa dicegah."},{"id":"e4","label":"Pipa endotrakeal: ukuran yang direncanakan ditambah satu lebih kecil dan satu lebih besar, kaf sudah diuji","correct":true,"why":"Ukuran bervariasi; kaf harus diuji sebelum digunakan."},{"id":"e5","label":"Stilet atau bougie","correct":true,"why":"Membantu bila pandangan sulit."},{"id":"e6","label":"Sungkup laring (supraglottic airway) sebagai alat cadangan","correct":true,"why":"Cadangan standar bila intubasi atau ventilasi masker sulit."},{"id":"e7","label":"Video laringoskop tersedia di ruangan","correct":true,"why":"Berguna bila kesulitan sudah diantisipasi."},{"id":"e8","label":"Kapnografi gelombang terpasang","correct":true,"why":"Diperlukan untuk memastikan posisi pipa."},{"id":"e9","label":"Set pemasangan chest drain","correct":false,"why":"Bukan bagian persiapan jalan napas rutin."},{"id":"e10","label":"Set kateter urin","correct":false,"why":"Tidak terkait manajemen jalan napas."},{"id":"e11","label":"Set jalur arteri","correct":false,"why":"Tidak diperlukan untuk manajemen jalan napas pada pasien ini."},{"id":"e12","label":"Pad defibrilator sudah ditempel pada pasien","correct":false,"why":"Defibrilator harus mudah dijangkau, tetapi pad tidak dipasang untuk induksi rutin."}]}'::jsonb from public.case_steps where case_id='airway-management' and step_key='s3'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('airway-management','s4',3,'sequence','Urutan intubasi',null,'Susun langkah seputar intubasi dalam urutan yang aman.','Manajemen Jalan Napas',false,false,null,null,'Peralatan diperiksa lebih dulu, lalu pasien diposisikan dan dipreoksigenasi. Setelah itu induksi dan intubasi dilakukan, diikuti konfirmasi posisi dan fiksasi pipa.','Periksa, posisikan, preoksigenasi, intubasi, konfirmasi, fiksasi.')
insert into public.questions (step_id,payload) select id, '{"items":[{"id":"i1","text":"Periksa suction, lampu laringoskop, kaf pipa, dan sirkuit bag-mask"},{"id":"i2","text":"Posisikan pasien untuk laringoskopi"},{"id":"i3","text":"Preoksigenasi dengan masker wajah yang pas"},{"id":"i4","text":"Bantu dokter anestesi saat induksi dan pemasangan pipa"},{"id":"i5","text":"Konfirmasi posisi pipa: kapnografi gelombang, gerakan dada, auskultasi"},{"id":"i6","text":"Fiksasi pipa dan catat kedalamannya"}]}'::jsonb from public.case_steps where case_id='airway-management' and step_key='s4'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('airway-management','s5',4,'branching','Tidak ada gelombang CO₂','Pipa sudah terpasang dan disambungkan ke sirkuit. Kapnografi TIDAK menunjukkan gelombang. Gerakan dada tidak jelas dan SpO₂ mulai turun.','Apa yang kamu lakukan?','Respons Darurat',true,false,'{"spo2":95,"hr":88}'::jsonb,null,'Tidak adanya gelombang CO₂ akhir-ekspirasi setelah intubasi berarti pipa harus dianggap salah posisi, atau sirkuit terlepas atau tersumbat, sampai terbukti sebaliknya. Kapnografi gelombang adalah konfirmasi paling andal untuk posisi di trakea. Segera lapor dan pertahankan oksigenasi.','Tanpa gelombang berarti tanpa konfirmasi. Lapor segera dan tetap oksigenasi.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Segera memberi tahu dokter anestesi bahwa tidak ada gelombang CO₂, tetap mengoksigenasi, dan membantu memeriksa ulang posisi pipa sesuai arahan","score":100,"consequence":"Dokter anestesi langsung mengetahui dan dapat menilai ulang jalan napas sementara oksigenasi dipertahankan."},{"id":"b","text":"Memeriksa sendiri selang sampling dan sambungan, lalu melapor hanya jika masalah berlanjut","score":40,"consequence":"Memeriksa sambungan itu wajar, tetapi menunda laporan tidak aman ketika pipa mungkin salah posisi."},{"id":"c","text":"Mengandalkan auskultasi dada dan melanjutkan, karena kapnografi hanya cadangan","score":0,"consequence":"Auskultasi saja bisa menyesatkan. Pipa mungkin tidak berada di trakea dan pasien mulai desaturasi.","remedial":"r1"},{"id":"d","text":"Memfiksasi pipa dengan plester dan menunggu beberapa menit apakah CO₂ muncul","score":0,"consequence":"Menunggu menunda pengenalan pipa yang mungkin salah posisi sementara kadar oksigen turun.","remedial":"r1"}]}'::jsonb from public.case_steps where case_id='airway-management' and step_key='s5'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('airway-management','r1',5,'mcq','Lanjutan: SpO₂ menurun','SpO₂ kini 88% dan masih turun. Gelombang kapnografi masih tidak ada.','Apa prioritasnya sekarang?','Respons Darurat',false,true,'{"spo2":88,"hr":104}'::jsonb,null,'SpO₂ yang turun tanpa konfirmasi ventilasi adalah keadaan darurat. Memanggil bantuan sejak dini dan mendukung oksigenasi adalah prioritas.','SpO₂ turun dan jalan napas belum terkonfirmasi: panggil bantuan lebih awal.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Segera memanggil bantuan, memberi tahu dokter anestesi, dan mendukung oksigenasi sementara posisi pipa dinilai ulang"},{"id":"b","text":"Menunggu SpO₂ pulih sendiri"},{"id":"c","text":"Mencatat nilainya dan lanjut menyiapkan duk steril"},{"id":"d","text":"Meminta dokter bedah mulai agar waktu tidak terbuang"}],"correct":"a"}'::jsonb from public.case_steps where case_id='airway-management' and step_key='r1'
insert into public.cases (id,number,title,category,difficulty,duration_min,summary,scenario,objectives,patient,vitals,history,"references",scoring,published) values ('before-induction-safety-check',3,'Pemeriksaan Keselamatan Sebelum Induksi','preparation','INTERMEDIATE',10,'Jalankan fase Sign In dan pemeriksaan peralatan sebelum anestesi, lalu hentikan tindakan bila pemeriksaan keselamatan gagal.','Pasien sudah berada di kamar operasi dan masih sadar. Sebelum induksi, tim melakukan fase Sign In pada daftar periksa keselamatan bedah dan pemeriksaan mesin serta peralatan anestesi. Kamu adalah perawat anestesi yang memastikan tidak ada yang terlewat.','["Menempatkan fase Sign In dalam daftar periksa keselamatan bedah","Mengingat urutan butir Sign In","Menemukan entri daftar periksa yang tidak aman","Memverifikasi mesin dan peralatan, serta merespons pemeriksaan yang gagal"]'::jsonb,'{"sex":"Laki-laki","age":45,"procedure":"Artroskopi lutut kiri elektif dengan anestesi umum","note":"ASA I"}'::jsonb,'{"bp":"126/80","hr":74,"spo2":99,"temp":36.6,"rr":14}'::jsonb,'["Tidak ada penyakit kronis, tidak minum obat rutin","Melaporkan kulit gatal setelah memakai sarung tangan lateks","Prosedur yang direncanakan: lutut KIRI","Puasa dikonfirmasi oleh pasien"]'::jsonb,'[{"title":"WHO Surgical Safety Checklist","org":"World Health Organization (WHO)"},{"title":"Pre-Anesthesia Checkout Procedures (anesthesia machine)","org":"ASA / petunjuk pabrikan"}]'::jsonb,null,true)
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('before-induction-safety-check','s1',0,'mcq','Fase yang mana?','Pasien berada di kamar operasi dalam keadaan sadar, dan induksi belum dimulai.','Fase mana dari WHO Surgical Safety Checklist yang berlaku sekarang?','Keselamatan',false,false,null,null,'Fase Sign In dilakukan sebelum induksi anestesi. Time Out sebelum insisi, dan Sign Out sebelum pasien meninggalkan ruangan.','Sign In = sebelum induksi. Time Out = sebelum insisi. Sign Out = sebelum keluar.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Sign In (sebelum induksi anestesi)"},{"id":"b","text":"Time Out (sebelum insisi kulit)"},{"id":"c","text":"Sign Out (sebelum pasien meninggalkan kamar operasi)"},{"id":"d","text":"Kunjungan poli pra-operasi"}],"correct":"a"}'::jsonb from public.case_steps where case_id='before-induction-safety-check' and step_key='s1'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('before-induction-safety-check','s2',1,'sequence','Urutan Sign In',null,'Susun butir Sign In sesuai urutannya pada daftar periksa WHO.','Keselamatan',false,false,null,null,'Bagian Sign In WHO dimulai dari identitas, lokasi, prosedur, dan persetujuan, lalu penandaan lokasi, pemeriksaan keselamatan anestesi, pulse oximeter, alergi, dan risiko jalan napas sulit atau aspirasi.','Hafalkan urutan daftar periksa agar tidak ada yang terlewat saat tertekan.')
insert into public.questions (step_id,payload) select id, '{"items":[{"id":"i1","text":"Konfirmasi identitas, lokasi, prosedur, dan persetujuan"},{"id":"i2","text":"Konfirmasi lokasi operasi sudah ditandai"},{"id":"i3","text":"Konfirmasi pemeriksaan keselamatan anestesi sudah lengkap"},{"id":"i4","text":"Konfirmasi pulse oximeter terpasang pada pasien dan berfungsi"},{"id":"i5","text":"Tanyakan alergi yang diketahui"},{"id":"i6","text":"Nilai risiko jalan napas sulit atau aspirasi"}]}'::jsonb from public.case_steps where case_id='before-induction-safety-check' and step_key='s2'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('before-induction-safety-check','s3',2,'find-error','Temukan entri yang tidak aman',null,'Tim telah mencentang butir Sign In berikut. Entri mana yang harus dikoreksi sebelum induksi?','Keselamatan',true,false,null,null,'Dua entri tidak aman: lokasi tidak ditandai saat pasien sadar, dan entri alergi bertentangan dengan riwayat. Keduanya harus diperbaiki sebelum induksi.','Kotak yang dicentang hanya aman jika sesuai dengan fakta.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Pilih semua entri yang salah atau tidak aman.","items":[{"id":"c1","label":"Pasien mengonfirmasi identitas, lokasi, prosedur, dan persetujuan","correct":false,"why":"Konfirmasi sudah benar."},{"id":"c2","label":"Penandaan lokasi: lutut kiri belum ditandai (''ditandai setelah induksi'')","correct":true,"why":"Lokasi harus ditandai saat pasien masih sadar dan dapat mengonfirmasinya."},{"id":"c3","label":"Pulse oximeter terpasang pada pasien dan berfungsi","correct":false,"why":"Benar."},{"id":"c4","label":"Alergi: ''Tidak ada alergi'' dicentang, padahal pasien melaporkan gatal dengan sarung tangan lateks","correct":true,"why":"Reaksi lateks yang dilaporkan bertentangan dengan entri yang dicentang dan harus diklarifikasi serta dikomunikasikan."},{"id":"c5","label":"Pemeriksaan keselamatan anestesi (mesin dan obat) selesai","correct":false,"why":"Benar."},{"id":"c6","label":"Risiko jalan napas sulit dan aspirasi sudah dinilai, alat tersedia","correct":false,"why":"Benar."}]}'::jsonb from public.case_steps where case_id='before-induction-safety-check' and step_key='s3'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('before-induction-safety-check','s4',3,'equipment','Pemeriksaan mesin dan peralatan',null,'Item mana yang termasuk pemeriksaan mesin dan peralatan anestesi?','Persiapan Peralatan',true,false,null,null,'Pemeriksaan pra-pakai mencakup suplai dan cadangan oksigen, uji kebocoran, cadangan ventilasi, suction, alarm monitor, dan scavenging. Hitung instrumen, tempat tidur, dan benang termasuk pemeriksaan lain.','Periksa hal-hal yang menjaga pasien tetap teroksigenasi, terventilasi, dan termonitor.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Pilih item yang harus diverifikasi sebelum induksi.","items":[{"id":"e1","label":"Suplai oksigen terhubung dan tabung oksigen cadangan tersedia","correct":true,"why":"Hilangnya suplai oksigen harus ada cadangannya."},{"id":"e2","label":"Uji kebocoran sirkuit napas dilakukan","correct":true,"why":"Mendeteksi kebocoran dan lepasnya sambungan."},{"id":"e3","label":"Self-inflating bag resusitasi siap","correct":true,"why":"Cadangan ventilasi yang independen."},{"id":"e4","label":"Suction berfungsi","correct":true,"why":"Diperlukan sebelum induksi."},{"id":"e5","label":"Alarm monitor terdengar dan batasnya sesuai","correct":true,"why":"Alarm hanya berguna bila menyala dan diatur dengan benar."},{"id":"e6","label":"Sistem scavenging gas terhubung","correct":true,"why":"Melindungi petugas dari gas anestesi sisa."},{"id":"e7","label":"Lembar hitung instrumen bedah","correct":false,"why":"Tugas tim bedah, bukan bagian pemeriksaan mesin."},{"id":"e8","label":"Penentuan tempat tidur pasca-operasi","correct":false,"why":"Bukan bagian pemeriksaan mesin."},{"id":"e9","label":"Pemilihan benang untuk penutupan luka","correct":false,"why":"Persiapan tim bedah."}]}'::jsonb from public.case_steps where case_id='before-induction-safety-check' and step_key='s4'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('before-induction-safety-check','s5',4,'branching','Uji kebocoran gagal','Saat uji kebocoran sirkuit, tekanan tidak bertahan. Kamu menduga ada sambungan longgar tetapi belum menemukannya. Tim menunggu.','Apa yang harus kamu lakukan?','Persiapan Peralatan',true,false,null,null,'Pemeriksaan pra-pakai yang gagal berarti mesin belum siap. Perbaiki atau ganti peralatan, ulangi pemeriksaan, dan beri tahu dokter anestesi sebelum induksi.','Pemeriksaan yang gagal menghentikan kasus sampai lulus.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Tidak melanjutkan ke induksi. Periksa ulang sambungan atau ganti sirkuit atau mesin, ulangi pemeriksaan, dan beri tahu dokter anestesi","score":100,"consequence":"Induksi ditunda sampai peralatan terbukti aman, dan dokter anestesi diberi tahu."},{"id":"b","text":"Lanjut, karena kebocoran kecil bisa dikompensasi dengan aliran gas segar lebih tinggi","score":0,"consequence":"Memulai dengan kebocoran yang diketahui berisiko ventilasi tidak adekuat dan gas tidak sampai ke pasien.","remedial":"r1"},{"id":"c","text":"Periksa ulang semua sambungan dan uji lagi, tetapi tidak memberi tahu siapa pun sampai selesai diperbaiki","score":40,"consequence":"Memeriksa ulang sudah benar, tetapi dokter anestesi harus tahu bahwa pemeriksaan gagal."},{"id":"d","text":"Lewati uji kebocoran karena mesin lulus pemeriksaan kemarin","score":0,"consequence":"Pemeriksaan pra-pakai harus dilakukan sebelum setiap kasus.","remedial":"r1"}]}'::jsonb from public.case_steps where case_id='before-induction-safety-check' and step_key='s5'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('before-induction-safety-check','r1',5,'mcq','Lanjutan: sirkuit pengganti','Sirkuit napas pengganti sudah dipasang.','Apa yang harus dilakukan sebelum mesin digunakan?','Persiapan Peralatan',false,true,null,null,'Setiap perubahan pada sistem napas mengharuskan pemeriksaan diulang. Inspeksi visual saja tidak dapat mendeteksi kebocoran.','Ganti peralatan, ulangi pemeriksaan.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Ulangi uji kebocoran dan pemeriksaan terkait pada rangkaian baru, lalu laporkan hasilnya ke dokter anestesi"},{"id":"b","text":"Tidak perlu apa-apa: sirkuit baru selalu aman"},{"id":"c","text":"Cukup periksa bahwa sirkuit tampak utuh"},{"id":"d","text":"Uji setelah induksi dimulai"}],"correct":"a"}'::jsonb from public.case_steps where case_id='before-induction-safety-check' and step_key='r1'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('before-induction-safety-check','s6',6,'mcq','Pelabelan obat','Semprit berisi obat anestesi telah disiapkan oleh tim dan berada di nampan.','Apa yang harus terpenuhi sebelum obat apa pun diberikan?','Keselamatan Obat',true,false,null,null,'Semprit tanpa label adalah sumber utama kesalahan pemberian obat. Setiap semprit harus diberi label dan diverifikasi sebelum diberikan.','Beri label pada semuanya, verifikasi sebelum memberikan.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Setiap semprit berlabel jelas (nama obat, konsentrasi) dan diverifikasi sebelum diberikan"},{"id":"b","text":"Semprit tanpa label boleh selama langsung digunakan"},{"id":"c","text":"Hanya semprit pertama yang perlu label"},{"id":"d","text":"Label bisa ditambahkan setelah kasus selesai"}],"correct":"a"}'::jsonb from public.case_steps where case_id='before-induction-safety-check' and step_key='s6'
insert into public.cases (id,number,title,category,difficulty,duration_min,summary,scenario,objectives,patient,vitals,history,"references",scoring,published) values ('perioperative-monitoring',4,'Monitoring Perioperatif','monitoring','BEGINNER',9,'Pasang monitoring dasar, temukan kesalahan pemasangan, dan tanggapi perubahan tekanan darah pasien.','Kamu menyiapkan monitoring untuk pasien yang dijadwalkan anestesi umum. Pilih dan periksa monitor, tafsirkan yang terlihat, dan merespons dengan benar saat tanda vital berubah selama operasi.','["Menyebutkan standar monitoring dasar untuk anestesi umum","Menyiapkan peralatan monitoring yang tepat","Menemukan kesalahan pemasangan monitoring","Merespons perubahan tanda vital"]'::jsonb,'{"sex":"Perempuan","age":29,"procedure":"Kistektomi ovarium laparoskopik elektif dengan anestesi umum","note":"ASA I"}'::jsonb,'{"bp":"118/72","hr":76,"spo2":99,"temp":36.6,"rr":14}'::jsonb,'["Tidak ada penyakit kronis, tidak minum obat rutin","Direncanakan anestesi umum dengan pelumpuh otot","Tidak ada alergi yang diketahui"]'::jsonb,'[{"title":"Standards for Basic Anesthetic Monitoring","org":"American Society of Anesthesiologists (ASA)"}]'::jsonb,null,true)
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('perioperative-monitoring','s1',0,'mcq','Standar dasar',null,'Kumpulan mana yang merupakan standar monitoring dasar untuk anestesi umum?','Monitoring',true,false,null,null,'Standar dasar mencakup oksigenasi (pulse oximetry), ventilasi (kapnografi), sirkulasi (EKG dan tekanan darah), dan suhu bila relevan secara klinis. Pulse oximetry saja hanya menunjukkan oksigenasi, bukan ventilasi.','Oksigenasi, ventilasi, sirkulasi, suhu. Satu monitor tidak bisa mencakup keempatnya.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Pulse oximetry, EKG, tekanan darah non-invasif, dan kapnografi, dengan suhu dipantau bila perubahan bermakna diantisipasi"},{"id":"b","text":"EKG saja"},{"id":"c","text":"Tekanan arteri invasif dan tekanan vena sentral untuk setiap pasien"},{"id":"d","text":"Pulse oximetry saja, karena menunjukkan oksigenasi sekaligus ventilasi"}],"correct":"a"}'::jsonb from public.case_steps where case_id='perioperative-monitoring' and step_key='s1'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('perioperative-monitoring','s2',1,'equipment','Siapkan monitor',null,'Item mana yang kamu siapkan?','Persiapan Peralatan',false,false,null,null,'Siapkan monitor dasar ditambah stimulator saraf karena pelumpuh otot direncanakan. Monitoring invasif dicadangkan untuk pasien atau prosedur yang membutuhkannya.','Sesuaikan monitor dengan pasien dan rencana anestesi.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Pilih peralatan monitoring yang disiapkan untuk pasien ini.","items":[{"id":"e1","label":"Probe pulse oximeter","correct":true,"why":"Monitor oksigenasi dasar."},{"id":"e2","label":"Elektroda dan kabel EKG","correct":true,"why":"EKG kontinu adalah standar dasar."},{"id":"e3","label":"Manset tekanan darah dengan ukuran yang tepat","correct":true,"why":"Manset yang salah ukuran memberi bacaan keliru."},{"id":"e4","label":"Selang sampling kapnografi","correct":true,"why":"Monitoring ventilasi untuk anestesi umum."},{"id":"e5","label":"Probe suhu","correct":true,"why":"Perubahan suhu diperkirakan terjadi selama anestesi."},{"id":"e6","label":"Stimulator saraf perifer","correct":true,"why":"Pelumpuh otot direncanakan, sehingga fungsi neuromuskular perlu dipantau."},{"id":"e7","label":"Kateter arteri pulmonalis","correct":false,"why":"Tidak diindikasikan untuk pasien sehat ini."},{"id":"e8","label":"Set kateter vena sentral","correct":false,"why":"Tidak diindikasikan secara rutin di sini."},{"id":"e9","label":"Set jalur arteri invasif","correct":false,"why":"Tidak rutin diindikasikan untuk pasien ASA I dan prosedur ini."}]}'::jsonb from public.case_steps where case_id='perioperative-monitoring' and step_key='s2'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('perioperative-monitoring','s3',2,'mcq','Memastikan ventilasi','Pasien sudah diintubasi. Monitor: SpO₂ 99%, HR 72, TD 112/68, EtCO₂ 37 mmHg dengan kapnogram teratur.','Temuan mana yang PALING memastikan pasien diventilasi dengan efektif?','Monitoring',false,false,'{"bp":"112/68","hr":72,"spo2":99,"etco2":37}'::jsonb,null,'Kapnografi menunjukkan langsung CO₂ yang dihembuskan sehingga mencerminkan ventilasi. SpO₂ bisa tetap tinggi beberapa saat meski ventilasi berhenti, terutama setelah preoksigenasi.','Kapnografi menunjukkan ventilasi. SpO₂ tertinggal di belakang.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Gelombang kapnogram teratur dengan nilai CO₂ akhir-ekspirasi normal"},{"id":"b","text":"Laju jantung di bawah 80"},{"id":"c","text":"SpO₂ 99% saja"},{"id":"d","text":"Tekanan darah tidak berubah"}],"correct":"a"}'::jsonb from public.case_steps where case_id='perioperative-monitoring' and step_key='s3'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('perioperative-monitoring','s4',3,'find-error','Pemasangan monitoring',null,'Telaah pemasangan monitoring saat ini. Entri mana yang bermasalah?','Monitoring',true,false,null,null,'Alarm yang dibisukan menghilangkan jaring pengaman penting, dan probe SpO₂ di lengan yang sama dengan manset menyebabkan sinyal hilang berulang.','Alarm menyala, probe dan manset di anggota gerak berbeda.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Pilih semua entri yang menunjukkan masalah monitoring.","items":[{"id":"c1","label":"Gambaran EKG jelas, kabel terpasang kuat","correct":false,"why":"Baik."},{"id":"c2","label":"Gelombang kapnogram ada, EtCO₂ tampil","correct":false,"why":"Baik."},{"id":"c3","label":"Probe suhu terpasang, nilai tampil","correct":false,"why":"Baik."},{"id":"c4","label":"Ukuran manset tekanan darah sesuai dengan lengan","correct":false,"why":"Baik."},{"id":"c5","label":"Alarm dibisukan agar tidak mengganggu dokter bedah","correct":true,"why":"Alarm adalah jaring pengaman. Harus tetap terdengar dengan batas yang sesuai."},{"id":"c6","label":"Probe SpO₂ di lengan yang sama dengan manset tekanan darah (sinyal hilang setiap manset mengembang)","correct":true,"why":"Pengembangan manset memutus sinyal pulse oximeter. Gunakan lengan lain atau lokasi lain."}]}'::jsonb from public.case_steps where case_id='perioperative-monitoring' and step_key='s4'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('perioperative-monitoring','s5',4,'mcq','Seberapa sering?',null,'Minimal seberapa sering tekanan darah dan laju jantung dievaluasi selama anestesi umum menurut standar monitoring dasar ASA?','Dokumentasi',false,false,null,null,'Standar ASA menyatakan tekanan darah arteri dan laju jantung dievaluasi setidaknya setiap lima menit selama anestesi. Protokol institusi dapat menuntut lebih sering.','Tekanan darah dan laju jantung minimal setiap 5 menit.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Setidaknya setiap 5 menit"},{"id":"b","text":"Setiap 30 menit"},{"id":"c","text":"Sekali saat induksi dan sekali saat emergence"},{"id":"d","text":"Hanya saat alarm berbunyi"}],"correct":"a"}'::jsonb from public.case_steps where case_id='perioperative-monitoring' and step_key='s5'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('perioperative-monitoring','s6',5,'branching','Tekanan darah turun','45 menit setelah operasi berjalan. Monitor kini menunjukkan TD 82/48 dan HR 112. Bacaan 5 menit lalu adalah 110/66.','Apa tindakan pertamamu?','Respons Darurat',true,false,'{"bp":"82/48","hr":112,"spo2":98,"etco2":34}'::jsonb,null,'Penurunan tekanan darah yang tajam disertai laju jantung naik adalah perubahan bermakna. Segera beri tahu dokter anestesi sambil memverifikasi bacaan dan melihat kemungkinan penyebab.','Laporkan perubahan bermakna lebih awal. Keputusan terapi ada pada dokter anestesi.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Segera memberi tahu dokter anestesi dan membantu memverifikasi bacaan (manset, gambaran) sambil mencari penyebab seperti perdarahan atau perubahan posisi","score":100,"consequence":"Dokter anestesi diberi tahu lebih awal dan bacaan diperiksa pada saat yang sama."},{"id":"b","text":"Mengulang siklus manset dan menunggu bacaan berikutnya sebelum memberi tahu siapa pun","score":40,"consequence":"Memverifikasi itu wajar, tetapi menunggu untuk memberi tahu dokter anestesi menunda respons terhadap tren yang nyata."},{"id":"c","text":"Menganggapnya artefak dan mengabaikannya","score":0,"consequence":"Perubahan tren yang jelas disertai laju jantung naik tidak boleh diabaikan."},{"id":"d","text":"Memberikan obat penaik tekanan darah tanpa instruksi","score":0,"consequence":"Keputusan pemberian obat ada pada dokter anestesi. Bertindak sendiri tidak aman."}]}'::jsonb from public.case_steps where case_id='perioperative-monitoring' and step_key='s6'
insert into public.cases (id,number,title,category,difficulty,duration_min,summary,scenario,objectives,patient,vitals,history,"references",scoring,published) values ('post-anesthesia-care',5,'Ruang Pemulihan Pasca-Anestesi (PACU)','post-anesthesia','INTERMEDIATE',10,'Terima pasien di PACU, lakukan serah terima yang aman, dan tanggapi pasien mengantuk dengan sumbatan jalan napas.','Seorang pasien baru tiba di ruang pemulihan pasca-anestesi setelah anestesi umum. Kamu adalah perawat pemulihan. Prioritaskan jalan napas dan pernapasan, terima serah terima terstruktur, kenali perawatan yang tidak aman, dan tanggapi pasien yang memburuk.','["Memprioritaskan tindakan saat pasien tiba di PACU","Mengenali unsur penting serah terima","Mengenali perawatan pemulihan yang tidak aman","Merespons sumbatan jalan napas di ruang pemulihan"]'::jsonb,'{"sex":"Laki-laki","age":61,"procedure":"Perbaikan hernia elektif, anestesi umum (sekitar 90 menit)","note":"Diekstubasi di akhir operasi"}'::jsonb,'{"bp":"138/86","hr":88,"spo2":95,"temp":35.9,"rr":12}'::jsonb,'["Diekstubasi di kamar operasi, dipindahkan dengan oksigen","Tidak ada alergi yang diketahui","Rencana analgesia sesuai instruksi dokter anestesi (lihat catatan anestesi)"]'::jsonb,'[{"title":"Practice Guidelines for Postanesthetic Care","org":"American Society of Anesthesiologists (ASA)"}]'::jsonb,null,true)
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('post-anesthesia-care','s1',0,'sequence','Prioritas saat tiba',null,'Susun tindakanmu saat pasien tiba di PACU.','Asesmen Pasien',true,false,null,null,'Jalan napas dan pernapasan didahulukan. Monitor memberi data objektif, lalu serah terima melengkapi konteks. Gejala dinilai berikutnya, dan semuanya didokumentasikan serta dinilai ulang secara berkala.','Jalan napas dan pernapasan dulu, lalu monitor, serah terima, dan penilaian lengkap.')
insert into public.questions (step_id,payload) select id, '{"items":[{"id":"i1","text":"Periksa kepatenan jalan napas dan pernapasan, berikan oksigen tambahan sesuai instruksi"},{"id":"i2","text":"Pasang monitor standar dan catat tanda vital awal"},{"id":"i3","text":"Terima serah terima terstruktur dari tim anestesi"},{"id":"i4","text":"Nilai nyeri, mual, suhu, dan area operasi"},{"id":"i5","text":"Dokumentasikan dan nilai ulang secara berkala"}]}'::jsonb from public.case_steps where case_id='post-anesthesia-care' and step_key='s1'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('post-anesthesia-care','s2',1,'mcq','Isi serah terima',null,'Informasi mana yang penting dalam serah terima dari tim anestesi?','Serah Terima',true,false,null,null,'Serah terima yang baik memberi perawat pemulihan apa yang dibutuhkan untuk merawat pasien dengan aman: siapa pasiennya, apa yang terjadi, apa yang perlu diwaspadai, dan apa rencananya.','Serah terima = siapa, apa yang terjadi, apa yang diwaspadai, apa selanjutnya.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Identitas, prosedur, teknik anestesi, alergi, kejadian selama operasi, dan rencana pasca-operasi"},{"id":"b","text":"Hanya nama dokter bedah dan nomor bangsal"},{"id":"c","text":"Hanya obat yang telah diberikan"},{"id":"d","text":"Data asuransi pasien"}],"correct":"a"}'::jsonb from public.case_steps where case_id='post-anesthesia-care' and step_key='s2'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('post-anesthesia-care','s3',2,'find-error','Telaah perawatan pemulihan','Lima belas menit setelah tiba, kamu menelaah catatan pemulihan dan kondisi di sisi tempat tidur.','Entri mana yang tidak aman?','Keselamatan',true,false,'{"spo2":94,"rr":12}'::jsonb,null,'Mendengkur menandakan sumbatan jalan napas atas parsial, dan pasien yang sedang pulih dari anestesi tidak boleh ditinggal tanpa pengawasan.','Mendengkur adalah tanda jalan napas, bukan tanda tidur nyenyak.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Pilih semua entri yang menunjukkan perawatan tidak aman.","items":[{"id":"c1","label":"Oksigen diberikan; SpO₂ dipantau terus-menerus","correct":false,"why":"Sesuai."},{"id":"c2","label":"Suction dan alat bag-mask tersedia di sisi tempat tidur","correct":false,"why":"Sesuai."},{"id":"c3","label":"Skor nyeri dicatat dengan skala numerik","correct":false,"why":"Sesuai."},{"id":"c4","label":"Suhu diperiksa, selimut hangat diberikan","correct":false,"why":"Sesuai untuk suhu yang sedikit rendah."},{"id":"c5","label":"Napas mendengkur tercatat, tidak ada tindakan karena ''dia cuma tidur''","correct":true,"why":"Mendengkur adalah tanda sumbatan jalan napas parsial dan perlu ditindaklanjuti."},{"id":"c6","label":"Pasien ditinggal sendirian 20 menit saat petugas istirahat","correct":true,"why":"Pasien di ruang pemulihan harus diawasi terus-menerus oleh petugas terlatih."}]}'::jsonb from public.case_steps where case_id='post-anesthesia-care' and step_key='s3'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('post-anesthesia-care','s4',3,'branching','Mengantuk dan mendengkur','Pasien mengantuk dan mengeluarkan suara mendengkur. SpO₂ turun menjadi 90% dan frekuensi napas 8 kali per menit.','Apa yang kamu lakukan pertama kali?','Respons Darurat',true,false,'{"spo2":90,"rr":8,"hr":96}'::jsonb,null,'Mendengkur dengan SpO₂ turun dan frekuensi napas lambat menandakan sumbatan jalan napas dan ventilasi tidak adekuat. Buka jalan napas, stimulasi, pastikan oksigen, dan panggil bantuan.','Jalan napas dulu: buka, beri oksigen, panggil bantuan.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Membuka jalan napas (chin lift atau jaw thrust), menstimulasi pasien, memastikan oksigen terkirim, dan memanggil dokter anestesi","score":100,"consequence":"Jalan napas terbuka, pengiriman oksigen terkonfirmasi, dan bantuan sedang datang."},{"id":"b","text":"Menambah oksigen dan mengamati tenang-tenang selama 15 menit lagi","score":40,"consequence":"Oksigen membantu, tetapi penyebabnya adalah sumbatan jalan napas. Tanpa membuka jalan napas dan memanggil bantuan, pasien bisa memburuk."},{"id":"c","text":"Membiarkannya tidur: mendengkur itu normal setelah anestesi","score":0,"consequence":"Mendengkur dengan SpO₂ turun dan napas lambat tidak normal. Jalan napas terancam.","remedial":"r1"},{"id":"d","text":"Menulis nilainya di catatan dan melanjutkan pekerjaan administrasi","score":0,"consequence":"Dokumentasi penting tetapi tidak bisa menggantikan tindakan segera.","remedial":"r1"}]}'::jsonb from public.case_steps where case_id='post-anesthesia-care' and step_key='s4'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('post-anesthesia-care','r1',4,'mcq','Lanjutan: tidak ada aliran udara','SpO₂ 86%. Pasien tidak merespons panggilan dan kamu melihat usaha napas di dada tetapi tidak mendengar aliran udara.','Apa yang dilakukan sekarang?','Respons Darurat',false,true,'{"spo2":86,"rr":6,"hr":108}'::jsonb,null,'Usaha napas di dada tanpa aliran udara berarti sumbatan jalan napas total. Ini keadaan darurat: panggil bantuan dan segera dukung jalan napas serta ventilasi.','Usaha napas tanpa aliran udara adalah keadaan darurat. Panggil bantuan dan dukung jalan napas.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Segera memanggil bantuan dan mendukung jalan napas serta ventilasi dengan bag-mask dan oksigen sampai dokter anestesi datang"},{"id":"b","text":"Menunggu lima menit lagi"},{"id":"c","text":"Memindahkan pasien ke bangsal"},{"id":"d","text":"Meminta keluarga membangunkannya"}],"correct":"a"}'::jsonb from public.case_steps where case_id='post-anesthesia-care' and step_key='r1'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('post-anesthesia-care','s5',5,'mcq','Skor pemulihan',null,'Parameter apa saja yang menyusun skor Aldrete yang dimodifikasi, yang lazim dipakai untuk menilai kesiapan keluar dari PACU?','Asesmen Pasien',false,false,null,null,'Skor Aldrete yang dimodifikasi mencakup lima area: aktivitas, pernapasan, sirkulasi, kesadaran, dan saturasi oksigen. Banyak unit juga memakai kriteria tambahan seperti nyeri dan mual.','Aldrete: aktivitas, pernapasan, sirkulasi, kesadaran, SpO₂.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Aktivitas, pernapasan, sirkulasi, kesadaran, dan saturasi oksigen"},{"id":"b","text":"Laju jantung, hemoglobin, glukosa, natrium, dan kalium"},{"id":"c","text":"Skor nyeri saja"},{"id":"d","text":"Lama operasi, jenis operasi, dokter bedah, dan jumlah perdarahan"}],"correct":"a"}'::jsonb from public.case_steps where case_id='post-anesthesia-care' and step_key='s5'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('post-anesthesia-care','s6',6,'equipment','Kesiapan sisi tempat tidur',null,'Peralatan mana yang kamu siapkan?','Persiapan Peralatan',false,false,null,null,'Sisi tempat tidur membutuhkan oksigen, suction, alat ventilasi dan jalan napas, monitor, serta cara memanggil bantuan. Item kamar operasi tidak diperlukan di sana.','Setiap tempat tidur pemulihan siap menghadapi kedaruratan jalan napas.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Pilih item yang harus siap di setiap tempat tidur PACU.","items":[{"id":"e1","label":"Sumber oksigen dengan alat penghantar","correct":true,"why":"Oksigen tambahan adalah standar."},{"id":"e2","label":"Suction dengan kateter","correct":true,"why":"Diperlukan untuk muntah atau sekret."},{"id":"e3","label":"Bag-valve-mask","correct":true,"why":"Untuk ventilasi bantu."},{"id":"e4","label":"Alat jalan napas oral dan nasal","correct":true,"why":"Untuk sumbatan jalan napas."},{"id":"e5","label":"Monitoring EKG, SpO₂, dan tekanan darah kontinu","correct":true,"why":"Deteksi dini perburukan."},{"id":"e6","label":"Sistem panggil darurat dan akses ke troli resusitasi","correct":true,"why":"Bantuan harus dapat dijangkau dengan cepat."},{"id":"e7","label":"Set instrumen bedah","correct":false,"why":"Tempatnya di kamar operasi."},{"id":"e8","label":"Vaporizer gas anestesi","correct":false,"why":"Bagian dari mesin anestesi, bukan tempat tidur pemulihan."},{"id":"e9","label":"Duk bedah steril","correct":false,"why":"Tidak diperlukan untuk pemulihan rutin."}]}'::jsonb from public.case_steps where case_id='post-anesthesia-care' and step_key='s6'
insert into public.cases (id,number,title,category,difficulty,duration_min,summary,scenario,objectives,patient,vitals,history,"references",scoring,published) values ('anaphylaxis-emergency',6,'Gawat Darurat: Dugaan Anafilaksis','emergency','ADVANCED',10,'Kenali reaksi alergi berat saat anestesi dan dukung tim pada menit-menit pertama.','Anestesi umum sudah diinduksi dan operasi telah dimulai. Beberapa menit setelah obat intravena baru diberikan, kondisi pasien berubah cepat. Kamu adalah perawat anestesi. Kenali masalahnya dan dukung dokter anestesi yang memimpin penanganan kedaruratan.','["Mengenali pola anafilaksis saat anestesi","Mengurutkan tindakan respons pertama","Menyiapkan peralatan yang tepat","Berkomunikasi dengan tim bedah dan mendokumentasikan"]'::jsonb,'{"sex":"Perempuan","age":35,"procedure":"Operasi kaki elektif dengan anestesi umum","note":"ASA I"}'::jsonb,'{"bp":"122/74","hr":80,"spo2":99,"temp":36.6,"etco2":36}'::jsonb,'["Sehat, tidak minum obat rutin","Tidak ada alergi sebelumnya yang dilaporkan","Antibiotik intravena dimulai beberapa menit lalu"]'::jsonb,'[{"title":"Anaphylaxis guidance","org":"World Allergy Organization (WAO)"},{"title":"Emergency treatment of anaphylactic reactions","org":"Resuscitation Council UK"}]'::jsonb,null,true)
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('anaphylaxis-emergency','s1',0,'mcq','Kenali','Lima menit setelah antibiotik intravena dimulai, monitor menunjukkan TD 70/38, HR 132, dan SpO₂ 91%. Tekanan jalan napas meningkat. Kamu melihat ruam merah berbercak di dada dan lengan pasien.','Apa kemungkinan masalah yang paling dulu dipikirkan?','Pengenalan Kegawatan',true,false,'{"bp":"70/38","hr":132,"spo2":91,"etco2":26}'::jsonb,null,'Hipotensi mendadak, takikardia, kenaikan tekanan jalan napas seperti bronkospasme, dan ruam kulit tak lama setelah obat baru sangat mengarah ke anafilaksis. Tanda kulit bisa tidak ada, sehingga polanya yang penting.','Obat baru disusul hipotensi mendadak, tanda jalan napas, dan ruam: pikirkan anafilaksis.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Anafilaksis: reaksi alergi berat terhadap obat yang baru diberikan"},{"id":"b","text":"Anestesi yang terlalu dangkal"},{"id":"c","text":"Reaksi vasovagal"},{"id":"d","text":"Hipotermia"}],"correct":"a"}'::jsonb from public.case_steps where case_id='anaphylaxis-emergency' and step_key='s1'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('anaphylaxis-emergency','s2',1,'sequence','Tindakan pertama',null,'Susun tindakan respons pertama dalam urutan yang logis.','Respons Darurat',true,false,null,null,'Pemicu dihentikan dan bantuan dipanggil segera. Oksigenasi dan dukungan jalan napas menyusul, lalu epinefrin dan dukungan sirkulasi sesuai arahan dokter anestesi. Dokumentasi dilengkapi begitu aman. Selalu ikuti protokol institusimu.','Hentikan pemicu, panggil bantuan, beri oksigen, lalu dukung terapi dokter anestesi.')
insert into public.questions (step_id,payload) select id, '{"items":[{"id":"i1","text":"Hentikan pemicu yang dicurigai (misalnya infus antibiotik)"},{"id":"i2","text":"Panggil bantuan dan beri tahu seluruh tim"},{"id":"i3","text":"Berikan oksigen 100% dan dukung jalan napas serta ventilasi"},{"id":"i4","text":"Siapkan epinefrin sesuai protokol institusi, sesuai arahan dokter anestesi"},{"id":"i5","text":"Dukung sirkulasi: akses IV berlubang besar dan cairan IV sesuai arahan"},{"id":"i6","text":"Dokumentasikan kronologi dan agen yang dicurigai; ambil sampel bila diminta"}]}'::jsonb from public.case_steps where case_id='anaphylaxis-emergency' and step_key='s2'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('anaphylaxis-emergency','s3',2,'equipment','Siapkan penanganan',null,'Item mana yang membantu tim dalam kedaruratan ini?','Persiapan Peralatan',true,false,null,null,'Siapkan epinefrin sesuai protokol, cairan dan akses, alat jalan napas dan ventilasi, serta peralatan resusitasi darurat. Obat yang dicurigai tidak boleh diberikan lagi.','Singkirkan pemicu, siapkan jalan napas, sirkulasi, dan alat penyelamatan.')
insert into public.questions (step_id,payload) select id, '{"instruction":"Pilih apa yang harus disiapkan atau dibawa ke sisi pasien.","items":[{"id":"e1","label":"Epinefrin tersedia sesuai protokol, siap untuk dokter anestesi","correct":true,"why":"Obat lini pertama pada anafilaksis. Dokter anestesi yang memutuskan pemberiannya."},{"id":"e2","label":"Kanul IV berlubang besar dan set cairan IV","correct":true,"why":"Dukungan sirkulasi."},{"id":"e3","label":"Suction dan alat jalan napas siap","correct":true,"why":"Jalan napas mungkin perlu dukungan cepat."},{"id":"e4","label":"Bag-valve-mask dengan oksigen 100%","correct":true,"why":"Cadangan ventilasi dan oksigenasi."},{"id":"e5","label":"Defibrilator dan troli resusitasi di dekat pasien","correct":true,"why":"Henti jantung adalah risiko bila pasien memburuk."},{"id":"e6","label":"Sisa antibiotik, untuk menyelesaikan infus","correct":false,"why":"Pemicu yang dicurigai tidak boleh diberikan lagi."},{"id":"e7","label":"Premedikasi sedatif","correct":false,"why":"Bukan bagian respons kedaruratan."},{"id":"e8","label":"Torniket","correct":false,"why":"Tidak diperlukan untuk kedaruratan ini."},{"id":"e9","label":"Set kateter urin","correct":false,"why":"Bukan item respons pertama."}]}'::jsonb from public.case_steps where case_id='anaphylaxis-emergency' and step_key='s3'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('anaphylaxis-emergency','s4',3,'branching','Komunikasi','Dokter bedah berkata: ''Kami hampir selesai dengan insisi. Boleh dilanjutkan?''','Bagaimana kamu menanggapi?','Komunikasi',true,false,null,null,'Dalam kedaruratan, seluruh tim harus berbagi informasi yang sama. Dokter anestesi memimpin respons medis, dan keputusan tentang operasi diambil bersama.','Komunikasi singkat, jelas, dan faktual kepada seluruh tim.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Menyampaikan dengan jelas bahwa pasien tidak stabil dengan dugaan anafilaksis, dokter anestesi yang memimpin, dan melanjutkan operasi adalah keputusan tim setelah pasien stabil","score":100,"consequence":"Dokter bedah mendapat fakta kuncinya dan keputusan diambil bersama dokter anestesi."},{"id":"b","text":"Menenangkan dokter bedah dan membiarkannya lanjut seperti biasa","score":0,"consequence":"Melanjutkan tanpa keputusan bersama membahayakan pasien yang tidak stabil."},{"id":"c","text":"Tidak berkata apa-apa dan menyerahkan komunikasi kepada orang lain","score":40,"consequence":"Diam membuat dokter bedah tidak terinformasi. Komunikasi yang singkat dan jelas adalah bagian dari perananmu."},{"id":"d","text":"Meminta dokter bedah bergegas agar waktu anestesi lebih singkat","score":0,"consequence":"Mempercepat operasi tidak mengobati kedaruratan dan menambah risiko."}]}'::jsonb from public.case_steps where case_id='anaphylaxis-emergency' and step_key='s4'
insert into public.case_steps (case_id,step_key,position,type,title,situation,prompt,tag,critical,remedial,vitals,reveal_history,explanation,takeaway) values ('anaphylaxis-emergency','s5',4,'mcq','Setelah stabil','Pasien sudah stabil dan akan dipindahkan ke area terpantau.','Tindak lanjut apa yang penting?','Dokumentasi',true,false,'{"bp":"108/64","hr":96,"spo2":97,"etco2":34}'::jsonb,null,'Gejala dapat kambuh sehingga pemantauan ketat berlanjut. Agen yang dicurigai dan reaksinya harus dicatat dan dikomunikasikan agar pasien terlindungi di masa depan dan dapat dievaluasi untuk alergi.','Dokumentasikan agen yang dicurigai, serah terima dengan jelas, tetap pantau.')
insert into public.questions (step_id,payload) select id, '{"options":[{"id":"a","text":"Mendokumentasikan reaksi dan agen yang dicurigai dengan jelas, serah terima ke tim penerima, tetap memantau ketat karena gejala dapat kembali, dan memastikan evaluasi alergi diatur"},{"id":"b","text":"Tidak perlu tindak lanjut begitu tanda vital normal"},{"id":"c","text":"Hanya memberi tahu keluarga, bukan mencatat di status"},{"id":"d","text":"Tidak mencatat kejadian ini agar staf lain tidak khawatir"}],"correct":"a"}'::jsonb from public.case_steps where case_id='anaphylaxis-emergency' and step_key='s5'
